-- Generated by `uv run python -m cli schema`; do not edit.
-- The app database: decks, jobs, files, users, spend.

BEGIN;

CREATE TABLE alembic_version (
    version_num VARCHAR(32) NOT NULL, 
    CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num)
);

-- Running upgrade  -> 0001

CREATE TABLE blobs (
    hash VARCHAR(64) NOT NULL, 
    data BYTEA NOT NULL, 
    content_type TEXT NOT NULL, 
    size INTEGER NOT NULL, 
    PRIMARY KEY (hash)
);

CREATE TABLE users (
    id TEXT NOT NULL, 
    email TEXT NOT NULL, 
    name TEXT NOT NULL, 
    avatar JSONB NOT NULL, 
    created TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
    PRIMARY KEY (id)
);

CREATE TABLE decks (
    id VARCHAR(32) NOT NULL, 
    user_id TEXT, 
    data JSONB NOT NULL, 
    version INTEGER NOT NULL, 
    aborted BOOLEAN NOT NULL, 
    history_at INTEGER NOT NULL, 
    created TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
    updated TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE INDEX ix_decks_updated ON decks (updated);

CREATE INDEX ix_decks_user_id ON decks (user_id);

CREATE TABLE deck_files (
    deck_id VARCHAR(32) NOT NULL, 
    name VARCHAR(128) NOT NULL, 
    hash VARCHAR(64) NOT NULL, 
    PRIMARY KEY (deck_id, name), 
    FOREIGN KEY(deck_id) REFERENCES decks (id) ON DELETE CASCADE, 
    FOREIGN KEY(hash) REFERENCES blobs (hash)
);

CREATE INDEX ix_deck_files_hash ON deck_files (hash);

CREATE TABLE events (
    deck_id VARCHAR(32) NOT NULL, 
    seq INTEGER NOT NULL, 
    data JSONB NOT NULL, 
    PRIMARY KEY (deck_id, seq), 
    FOREIGN KEY(deck_id) REFERENCES decks (id) ON DELETE CASCADE
);

CREATE TABLE jobs (
    id VARCHAR(64) NOT NULL, 
    kind VARCHAR(16) NOT NULL, 
    deck_id VARCHAR(32) NOT NULL, 
    user_id TEXT, 
    state VARCHAR(8) NOT NULL, 
    created FLOAT NOT NULL, 
    attempts INTEGER NOT NULL, 
    payload TEXT NOT NULL, 
    beat FLOAT, 
    PRIMARY KEY (id), 
    FOREIGN KEY(deck_id) REFERENCES decks (id) ON DELETE CASCADE
);

CREATE INDEX ix_jobs_deck_id ON jobs (deck_id);

CREATE INDEX ix_jobs_state_created ON jobs (state, created);

CREATE TABLE kept (
    deck_id VARCHAR(32) NOT NULL, 
    slide_id VARCHAR(64) NOT NULL, 
    html TEXT NOT NULL, 
    css TEXT NOT NULL, 
    origin TEXT NOT NULL, 
    PRIMARY KEY (deck_id, slide_id), 
    FOREIGN KEY(deck_id) REFERENCES decks (id) ON DELETE CASCADE
);

CREATE TABLE ledger (
    id SERIAL NOT NULL, 
    user_id TEXT, 
    deck_id VARCHAR(32), 
    at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
    cost_usd FLOAT NOT NULL, 
    data JSONB NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(deck_id) REFERENCES decks (id) ON DELETE SET NULL, 
    FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE INDEX ix_ledger_at ON ledger (at);

CREATE INDEX ix_ledger_deck_id ON ledger (deck_id);

CREATE INDEX ix_ledger_user_id ON ledger (user_id);

CREATE TABLE questions (
    deck_id VARCHAR(32) NOT NULL, 
    data JSONB NOT NULL, 
    PRIMARY KEY (deck_id), 
    FOREIGN KEY(deck_id) REFERENCES decks (id) ON DELETE CASCADE
);

CREATE TABLE versions (
    id SERIAL NOT NULL, 
    deck_id VARCHAR(32) NOT NULL, 
    n INTEGER NOT NULL, 
    label TEXT NOT NULL, 
    deck JSONB NOT NULL, 
    kept JSONB NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(deck_id) REFERENCES decks (id) ON DELETE CASCADE
);

CREATE INDEX ix_versions_deck_n ON versions (deck_id, n);

CREATE TABLE version_files (
    version_id INTEGER NOT NULL, 
    name VARCHAR(128) NOT NULL, 
    hash VARCHAR(64) NOT NULL, 
    PRIMARY KEY (version_id, name), 
    FOREIGN KEY(hash) REFERENCES blobs (hash), 
    FOREIGN KEY(version_id) REFERENCES versions (id) ON DELETE CASCADE
);

CREATE INDEX ix_version_files_hash ON version_files (hash);

INSERT INTO alembic_version (version_num) VALUES ('0001') RETURNING alembic_version.version_num;

COMMIT;

